import{_ as n,l as o,o as t,c as s,v as e,p as l,x as r,d as B,i as h,S as p}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Yi 技术报告","description":"","frontmatter":{"title":"Yi 技术报告","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/yi-report.md","filePath":"llm/yi-report.md","lastUpdated":1789023840000}'),d={name:"llm/yi-report.md"};function A(E,a,m,c,g,T){const i=o("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e('<h1 id="yi-技术报告" tabindex="-1">Yi 技术报告 <a class="header-anchor" href="#yi-技术报告" aria-label="Permalink to &quot;Yi 技术报告&quot;">​</a></h1><div class="epigraph"><p>34B 小到能在 24GB 卡上 INT4 推理，却用 3.1T 高质量中英语料过训；对齐不堆百万指令，而是把不到一万条样本逐条打磨。</p><footer>—— 01.AI，Yi: Open Foundation Models by 01.AI，arXiv:2403.04652</footer></div><p>零一万物 2023 年 11 月开源、2024 年 3 月成文的 <strong>Yi</strong> 是 6B / 34B 稠密解码器家族：Base、Chat、200K 长窗、深度上采样、视觉语言。报告把成绩主要归因于 <strong>数据工程</strong>，而不是改 Transformer 公式。预训练 <strong>3.1T</strong> 中英，级联去重与质量过滤；SFT <strong>少于 10K</strong>，每条由工程师多轮修订。本篇只写 2403.04652；<a href="/llm/yi-15">Yi-1.5</a> 的 500B 继续训与 <a href="/llm/yi-lightning">Yi-Lightning</a> 的 MoE 是后话，不要读进这篇。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>消费卡 24GB 装不下 70B，Chinchilla 最优又暗示 34B 只该吃约 1T。01.AI 的选择是：<strong>把模型定在 34B</strong>（INT4 后可进 4090），<strong>把 token 加到 3.1T</strong>，走进「过训、推理更便宜」的区间。中英双语不能靠英文 Common Crawl 滤完再翻译；中文网页黄赌毒与广告比例高，启发式不够，必须上学习型过滤器。</p><p>对齐若走 FLAN / UltraChat 百万级，单条质量无法人工看完。报告站在 <a href="/llm/lima">LIMA</a> 一侧：宁少而精。还要把窗口从预训练 4K 拉到 200K 针测，并把视觉编码器接到 Chat 语义空间，同时试深度上采样——三条都是「继续训释放已有能力」，不是从零换骨架。</p><h3 id="过训是为了服务成本" tabindex="-1">过训是为了服务成本 <a class="header-anchor" href="#过训是为了服务成本" aria-label="Permalink to &quot;过训是为了服务成本&quot;">​</a></h3><p>34B×3.1T 的 FLOPs 高于计算最优，换来的是同质量下更小的 decode 权重流。量化后「几乎不掉点」是报告的部署主张。6B 证明同一套数据管线在小模型上也成立，并同样上 <a href="/llm/gqa">GQA</a>——Llama 2 只在 70B 用 GQA，Yi 从 6B 就开始用。</p><p><span class="marginnote">词表 64000，BPE + SentencePiece，数字切 digit，罕见字符走 byte，不用 dummy prefix（中英句首引号会破坏「词前空白」假设）。与后来 Lightning 的 100352 词表不是同一套。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>数据管线：Common Crawl 经 CCNet 做语言识别与困惑度 → 启发式（URL/词表黑名单、长度与符号比、重复 n-gram）并匿名化 PII → 学习型过滤器（KenLM 困惑度、类维基质量分类器、文档连贯性、安全）→ 语义聚类打质量标签 → MinHash 文档去重加子文档精确去重 → 主题模型降采样广告。报告强调删除比例高于 CCNet / RefinedWeb / RedPajama，原则是 <strong>3T 精料优于 10T 粗料</strong>。配比图为中英多源，与纯英文 Llama / Falcon 混合物不同。</p><p>结构基于 Llama 实现：Yi-6B 隐藏 4096、32 查询头 / <strong>4 KV 头</strong>、32 层、预训练长 4096、峰值 LR \\(3\\times 10^{-4}\\)；Yi-34B 隐藏 7168、56 / <strong>8</strong> KV 头、60 层、峰值 LR \\(1.5\\times 10^{-4}\\)。SwiGLU 中间维按 \\(8/3\\,h\\) 收，补回 GQA 少掉的参数。RoPE，长窗用 <strong>ABF</strong> 调基频。</p><h3 id="少于-10k-的-sft" tabindex="-1">少于 10K 的 SFT <a class="header-anchor" href="#少于-10k-的-sft" aria-label="Permalink to &quot;少于 10K 的 SFT&quot;">​</a></h3><p>多轮对话，全部人工打磨多迭代。提示走 WizardLM 式复合进化以减样本；回答默认引言–要点列表–收束；思维链用 Step-Back 先抽象再解题。去幻觉：删掉模型知识范围外却写得像事实的回答；去重复：改写微调数据里被忽略的循环句。能力面用标签体系做多样性采样，配比在 \\(\\{1,1/2,\\ldots,1/64\\}\\) 上近似网格搜。格式用 <strong>ChatML</strong> 区分 system / user / assistant。损失只算回复 token。AdamW，序列 4096，batch 64，<strong>300 step</strong>，恒定 LR \\(1\\times 10^{-5}\\)，Yi-34B-Chat 用 NEFTune 噪声尺度 45（6B 为 5）。</p><h3 id="_200k、视觉与深度上采样" tabindex="-1">200K、视觉与深度上采样 <a class="header-anchor" href="#_200k、视觉与深度上采样" aria-label="Permalink to &quot;200K、视觉与深度上采样&quot;">​</a></h3><p>长上下文：在约 <strong>5B</strong>（正文亦写从混合中取约 10B、实际上 1–2B 已能把 4K–200K 损失压低）长度上采样的书等数据上轻量继续预训练，再轻量微调，针测接近满分。报告倾向认为 <strong>超 4K 依赖是基座已有的内禀能力</strong>，继续训只是释放。视觉：Chat 语言模型 + ViT，多阶段把视觉表示对齐到语言语义空间。深度上采样：加层后继续训，确认还能涨点。这与单纯加宽不同，计算图变长、服务 KV 也按层涨，只适合作为研究型检查点，不是 34B 默认交付。基础设施：跨云弹性调度、故障自动恢复、拓扑感知分配；微调框架可在同一作业里混 Megatron 与 DeepSpeed（DPO 参考模型）；推理 4bit 权 + 8bit KV，PagedAttention 与动态 batch。</p>',16)),(t(),l(p,null,{default:r(()=>[h(i,{id:"mermaid-46",class:"mermaid",graph:"flowchart%20TD%0A%20%20RAW%5B%22CC%20%2B%20%E4%B8%AD%E8%8B%B1%E5%A4%9A%E6%BA%90%22%5D%20--%3E%20PIPE%5B%22%E7%BA%A7%E8%81%94%E8%BF%87%E6%BB%A4%E4%B8%8E%E5%BC%BA%E5%8E%BB%E9%87%8D%20%E2%86%92%203.1T%22%5D%0A%20%20PIPE%20--%3E%20BASE%5B%22Yi-6B%20%2F%2034B%20Base%EF%BC%8CGQA%22%5D%0A%20%20BASE%20--%3E%20SFT%5B%22SFT%20%EF%BC%9C10K%20ChatML%22%5D%0A%20%20BASE%20--%3E%20CTX%5B%22%E7%BB%A7%E7%BB%AD%E8%AE%AD%E9%87%8A%E6%94%BE%20200K%22%5D%0A%20%20BASE%20--%3E%20DUS%5B%22%E6%B7%B1%E5%BA%A6%E4%B8%8A%E9%87%87%E6%A0%B7%22%5D%0A%20%20SFT%20--%3E%20VL%5B%22ViT%20%E5%AF%B9%E9%BD%90%20Chat%20%E7%A9%BA%E9%97%B4%22%5D%0A%20%20SFT%20--%3E%20Q%5B%22INT4%20%2F%208bit%20KV%20%E6%B6%88%E8%B4%B9%E5%8D%A1%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=e('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>GQA 从 6B 就上，说明他们把 KV 字节当成 24GB 卡的硬约束，而不是 70B 才需要的优化。过训改变的是 <strong>每个参数见过的 token 数</strong>：34B 在 3.1T 上把通识密度打满，推理期不必上 70B。SFT 少样本能工作，前提是基座已经从 3.1T 里学到格式与知识，10K 只校准「怎么说」；这与百万合成指令刷基准是反方向。</p><p>长窗机制：ABF 改 RoPE 基频 + 少量长序列继续训。作者把「1–2B token 即收敛」解读为能力内禀——这是他们的理论倾向，不是社区已证明的定理。深度上采样增加层深、在原检查点上继续训，走的是「加深度比加宽度更便宜地换表达力」的经验，报告未声称取代继续堆 3.1T。</p><p><span class="marginnote">Base 表：Yi-34B MMLU 76.3、C-Eval 81.4、CMMLU 83.7（报告分组表）。Chat 另报 AlpacaEval 与 Arena。不要用 Base MMLU 去对 Chat 的人类偏好。</span></p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Yi 第一代默认窗是 4K，200K 是独立检查点。代码与数学在 2024 年 3 月的表上相对通识偏弱，这正是 1.5 用 500B 去补的缺口。视觉与深度上采样是扩展章，不是 6B/34B 默认权重。许可证以当时 01.AI 仓库为准（后续 1.5 才全面 Apache 2.0 叙事）。</p><p>不要把 Lightning 的细粒度 MoE、100352 词表、RAISE 写进本篇。量化「几乎不掉点」依赖于他们的评测协议；业务上的长尾中文仍要以本机抽测为准。基础设施章节还写了跨云抢占、故障自动恢复与拓扑感知排卡，用来支撑「千卡月级」预训练；微调侧把参考模型前向缓存下来，使 DPO 的墙钟接近 SFT。这些是系统贡献，不改变 3.1T 与 10K 指令这两条算法主线。Chat 在 Arena / AlpacaEval 上的人类偏好，是少样本打磨加基座过训的联合结果，缺任一端都复现不了「接近 GPT-3.5」的叙事。视觉多阶段对齐只把 CLIP 形编码器接到冻结或半冻结的 Chat 空间，并不把 Yi 改成原生多模态预训练。</p><p><span class="marginnote">SFT 300 step、batch 64、少于 10K 条：总更新次数很少。换一套未打磨的 10K 公开指令，不能复现 Arena 体验。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Yi-6B/34B：3.1T 中英精料、全系列 GQA、RoPE ABF；对齐 $\\lt$10K 人工指令 + ChatML。</li><li>34B 过训是为了 INT4 消费卡推理，而不是追求 Chinchilla 最优。</li><li>200K、VL、深度上采样都是轻量继续训扩展，默认 Base 仍是 4K。</li><li>出处：01.AI，<em>Yi: Open Foundation Models by 01.AI</em>，arXiv:2403.04652，2024。</li></ul>',10))])}const u=n(d,[["render",A]]);export{_ as __pageData,u as default};
